diff --git a/js/common/dynamicRepoSetup.js b/js/common/dynamicRepoSetup.js
new file mode 100644
index 0000000000..8c1ada78cd
--- /dev/null
+++ b/js/common/dynamicRepoSetup.js
@@ -0,0 +1,55 @@
+/**
+ * Dynamic-Repository setup chaining (gh-823-safe shared helper)
+ *
+ * Each dmtools JS hook is a separate GraalJS invocation, so a
+ * targetRepository resolved in preJSAction does NOT survive to
+ * preCliJSAction.  The dynamic-repo agents therefore resolve the repo and run
+ * the setup action inside ONE hook; this helper is that single call so the
+ * development and story-test-automation wrappers do not duplicate it.
+ *
+ * Steps:
+ *   1. resolveRepoFromTicket.action(params)  → params.customParams.targetRepository
+ *   2. write the resolved workingDir to .dmtools-target-workingdir so CLI
+ *      shell scripts (e.g. create_test_commit.sh) can find the dependency
+ *      dir without re-implementing the [repo] parsing; skipped in dryRun,
+ *      non-fatal on failure.
+ *   3. run the supplied setup action with the resolved targetRepository.
+ *
+ * Returns false when the resolver aborts, otherwise the setup result.
+ */
+
+var resolveRepo = require('../resolveRepoFromTicket.js');
+var branchSetup = require('./branchSetup.js');
+
+function workingDirFromDynamicParams(params) {
+    var customParams = (params.jobParams && params.jobParams.customParams) || params.customParams || {};
+    var targetRepo = customParams.targetRepository || {};
+    return targetRepo.workingDir || '';
+}
+
+function writeResolvedWorkingDirFile(params, caller) {
+    if (branchSetup.isDryRunParams(params)) return;
+    var workingDir = workingDirFromDynamicParams(params);
+    if (!workingDir) return;
+    try {
+        file_write({ path: '.dmtools-target-workingdir', content: workingDir });
+        console.log(caller + ': wrote workingDir to .dmtools-target-workingdir:', workingDir);
+    } catch (e) {
+        console.warn(caller + ': could not write .dmtools-target-workingdir (non-fatal):', e);
+    }
+}
+
+function action(params, setupAction, caller) {
+    var label = caller || 'dynamicRepoSetup';
+    var resolved = resolveRepo.action(params);
+    if (resolved === false) {
+        console.warn(label + ': resolveRepoFromTicket returned false — aborting');
+        return false;
+    }
+    writeResolvedWorkingDirFile(params, label);
+    return setupAction(params);
+}
+
+if (typeof module !== 'undefined') {
+    module.exports = { action: action };
+}
diff --git a/js/postStoryTestAutomationResultsDynamicRepo.js b/js/postStoryTestAutomationResultsDynamicRepo.js
new file mode 100644
index 0000000000..ee15bd570b
--- /dev/null
+++ b/js/postStoryTestAutomationResultsDynamicRepo.js
@@ -0,0 +1,30 @@
+/**
+ * Post-Action Story Test Automation — Dynamic Repository variant
+ *
+ * Chains resolveRepoFromTicket + postStoryTestAutomationResults in a single
+ * GraalJS execution so that the resolved targetRepository (repo, baseBranch,
+ * workingDir, owner) is visible when configLoader.loadProjectConfig() is
+ * called inside postStoryTestAutomationResults.
+ *
+ * Used by: story_test_automation_dynamic_repo.json (postJSAction)
+ *
+ * Why a wrapper instead of direct postJSAction?
+ * Each dmtools JS hook (preJSAction, preCliJSAction, postJSAction) is a separate
+ * GraalJS invocation; params mutations made in one hook do NOT survive to the next.
+ * Running resolveRepo + results processing in the same call keeps targetRepository in scope.
+ */
+
+var resolveRepo = require('./resolveRepoFromTicket.js');
+var postResults = require('./postStoryTestAutomationResults.js');
+
+function action(params) {
+    // 1. Re-resolve target repo from ticket summary into params
+    resolveRepo.action(params);
+
+    // 2. Run standard post-action (commit + push + PR) with resolved config
+    return postResults.action(params);
+}
+
+if (typeof module !== 'undefined') {
+    module.exports = { action: action };
+}
diff --git a/js/preCliStoryTestAutomationSetupDynamicRepo.js b/js/preCliStoryTestAutomationSetupDynamicRepo.js
new file mode 100644
index 0000000000..f912c07845
--- /dev/null
+++ b/js/preCliStoryTestAutomationSetupDynamicRepo.js
@@ -0,0 +1,20 @@
+/**
+ * Pre-CLI Story Test Automation Setup — Dynamic Repository variant
+ *
+ * Used by: story_test_automation_dynamic_repo.json (preCliJSAction)
+ *
+ * Thin wrapper: resolveRepoFromTicket + .dmtools-target-workingdir marker +
+ * preCliStoryTestAutomationSetup run inside ONE GraalJS hook via the shared
+ * js/common/dynamicRepoSetup.js (params mutations do not survive across hooks).
+ */
+
+var dynamicRepoSetup  = require('./common/dynamicRepoSetup.js');
+var setupTestAutomation = require('./preCliStoryTestAutomationSetup.js');
+
+function action(params) {
+    return dynamicRepoSetup.action(params, setupTestAutomation.action, 'preCliStoryTestAutomationSetupDynamicRepo');
+}
+
+if (typeof module !== 'undefined') {
+    module.exports = { action: action };
+}

